// v5.4: Android 返回键钩子（热更，不动 android/**）。Java 侧 BackHandler 调 window.__SP_BACK()：
// 返回 true = 页面已消费（不要再走系统回退）；false = 交给系统（退回桌面 / 退出）。
// 同步函数；任何异常一律返回 false —— 宁可退回系统行为，也不要把返回键卡死。
/** 离开当前同盟 / 对局并回到首页（标题页）。 */
function spBackToHome() {
  try {
    const p = net.request('room.leave', {});
    if (p && typeof p.catch === 'function') p.catch(() => {});
  } catch (e) { /* 离线 / 旧协议：本地状态照常清 */ }
  store.set({ room: null, match: emptyMatch() });
  const s = store.get();
  store.set({ session: Object.assign({}, s.session, { entered: false }) });
}

window.__SP_BACK = function () {
  try {
    // 1) 覆盖层（游戏弹窗 / 壳的 in-page 面板）优先关闭并消费返回键。
    let overlay = false;
    try { overlay = !!document.querySelector('.modal'); } catch (e) { overlay = false; }
    if (overlay) {
      try { closeAllDialogs(); } catch (e) { /* ignore */ }
      // 壳面板（服务器 / 大厅 / 参数…）也走 .modal：openPanel(null) 关掉它（旧壳无面板，天然 no-op）。
      try {
        if (window.__SP_SHELL && typeof window.__SP_SHELL.openPanel === 'function') window.__SP_SHELL.openPanel(null);
      } catch (e) { /* ignore */ }
      return true;
    }
    const s = store.get();
    // 2) 标题页：交给系统（退到后台 / 退出）。
    if (selectRoute(s) === 'title') return false;
    // 3) 对局中：弹确认，确认后离开并回首页；取消则不动作。两种情况都已消费返回键。
    if (s.match && s.match.public && s.match.public.phase) {
      try {
        confirmDialog({
          title: '退出对局',
          text: '正在对局中，退出并回到首页？',
          okText: '退出',
          danger: true,
        }).then((ok) => { if (ok) spBackToHome(); }).catch(() => {});
      } catch (e) { /* ignore */ }
      return true;
    }
    // 4) 房间 / 大厅：离开同盟并回首页。
    spBackToHome();
    return true;
  } catch (e) {
    return false;
  }
};
